procedure OrchardReorder {
  about "Reorder crates below their minimum"
  policy OrchardPolicy
  sheet Stock "Stock" { item: Text, crates: Number, minimum: Number, reorder_crates: Number, supplier: Text, crate_price: Money }
  trigger every day at 06:30

  let all = fetch Stock
  let low = filter all where crates < minimum
  for each i in low up to 5 {
    if i.reorder_crates * i.crate_price > $200.00 {
      notify owner "Reorder of {i.item} would go over $200. Please review."
      skip
    }
    if i.reorder_crates * i.crate_price > $1000.00 {
      notify owner "Reorder of {i.item} would go over $1000. Please review."
      skip
    }
    order "{i.reorder_crates} x {i.item}" from i.supplier cost i.reorder_crates * i.crate_price, ask owner first timeout 12 hours else skip
    notify owner "Ordered {i.item}."
  }
}

