procedure OrchardOrder {
  about "Orders can be expensive! Please review them."
  policy OrchardPolicy
  sheet Stock "Stock" { item: Text, crates: Number, minimum: Number, reorder_crates: Number, supplier: Text, crate_price: Money }
  trigger every monday at 07:00

  let all = fetch Stock
  let these1 = filter all where item == "honeycrisp"
  let these2 = filter all where item == "grapefruit"
  let these3 = filter all where item == "orange"
  if these1.crates > $600.00 {
    notify owner "Over $600.00 ordering honeycrisp! Please review."
    stop "over the limit"
  }
  if these2.crates > $600.00 {
    notify owner "Over $600.00 ordering grapefruit! Please review."
    stop "over the limit"
  }
  if these3.crates > $600.00 {
    notify owner "Over $600.00 ordering orange! Please review."
    stop "over the limit"
  }
  order "{these1.crates} crates of {these1.item}" from "Hilltop Packers" cost these1.crate_price * these1.crates, ask owner first timeout 1 day else stop "first order not approved"
  order "{these2.crates} crates of {these2.item}" from "Hilltop Packers" cost these2.crate_price * these2.crates, ask owner first timeout 1 day else stop "second order not approved"
  order "{these3.crates} crates of {these3.item}" from "Hilltop Packers" cost these3.crate_price * these3.crates, ask owner first timeout 1 day else stop "third order not approved"
}

